const QUESTION = "Find the top 20 reviews of the AirPods Pro on Amazon and tell me what people complain about most.";

const SceneTyping: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps: vfps } = useVideoConfig();

  // Window persists (continuous feel) — fade in fast since transition handles it
  const windowIn = springIn(frame, vfps, 0, "LIQUID");

  // Realistic typing: ~2.2 chars per frame at 25fps = ~55 cps, but we want it slower (human-paced)
  // Type from frame ~10 to frame ~145, then hold
  const typingStart = 10;
  const typingEnd = 145;
  const typeProgress = interpolate(frame, [typingStart, typingEnd], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const charsToShow = Math.floor(typeProgress * QUESTION.length);
  const visibleText = QUESTION.slice(0, charsToShow);

  // Cursor blink
  const cursorOn = Math.floor(frame / 8) % 2 === 0;

  const inputDrift = ambientDrift(frame, 1, 130, "input-drift-2");

  return (
    <AbsoluteFill style={{ fontFamily: "'GT Walsheim', Inter, sans-serif" }}>
      <ClaudeWindow appearProgress={windowIn}>
        {/* Empty state still visible, slightly faded */}
        <div
          style={{
            position: "absolute",
            inset: 0,
            display: "flex",
            flexDirection: "column",
            alignItems: "center",
            justifyContent: "center",
            opacity: interpolate(typeProgress, [0, 0.3], [1, 0.25], {
              extrapolateRight: "clamp",
            }),
          }}
        >
          <div
            style={{
              fontFamily: "'GT Walsheim', Inter, sans-serif",
              fontWeight: 600,
              fontSize: 96,
              color: COLORS.textMuted,
              letterSpacing: "-0.02em",
            }}
          >
            How can I help you today?
          </div>
        </div>

        {/* Chat input — now with typed text */}
        <div
          style={{
            position: "absolute",
            left: "8%",
            right: "8%",
            bottom: "8%",
            backgroundColor: COLORS.bg,
            border: `1px solid ${
              typeProgress > 0 ? COLORS.orange : COLORS.border
            }`,
            borderRadius: 24,
            padding: "32px 40px",
            display: "flex",
            alignItems: "center",
            gap: 24,
            minHeight: 120,
            transform: `translateY(${inputDrift}px)`,
            transition: "border-color 0.2s ease",
          }}
        >
          <div
            style={{
              fontFamily: "Inter, sans-serif",
              fontSize: 40,
              color: COLORS.text,
              flex: 1,
              fontWeight: 400,
              lineHeight: 1.4,
            }}
          >
            {visibleText}
            <span
              style={{
                opacity: cursorOn ? 1 : 0,
                color: COLORS.orange,
                marginLeft: 2,
                fontWeight: 400,
              }}
            >
              |
            </span>
          </div>
          <div
            style={{
              width: 56,
              height: 56,
              borderRadius: "50%",
              backgroundColor:
                typeProgress > 0.95 ? COLORS.orange : COLORS.card,
              border: `1px solid ${
                typeProgress > 0.95 ? COLORS.orange : COLORS.border
              }`,
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              fontFamily: "'GT Walsheim', Inter, sans-serif",
              fontSize: 32,
              color: typeProgress > 0.95 ? "#fff" : COLORS.textSubtle,
              fontWeight: 600,
              flexShrink: 0,
            }}
          >
            ↑
          </div>
        </div>
      </ClaudeWindow>
    </AbsoluteFill>
  );
};

