            fontFamily: "'GT Walsheim', Inter, sans-serif",
            fontWeight: 600,
            fontSize: 130,
            color: COLORS.text,
            letterSpacing: "-0.025em",
            lineHeight: 1.05,
            textAlign: "center",
            opacity: headIn,
            transform: `translateY(${interpolate(headIn, [0, 1], [22, 0])}px)`,
          }}
        >
          Connect{" "}
          <span
            style={{
              display: "inline-block",
