const totalFrames =
  SCENE_COLD_OPEN +
  SCENE_TYPING +
  SCENE_CLAUDE_WORKS +
  SCENE_PAYOFF +
  SCENE_END_CARD -
  TRANSITION * 4;

export const durationInFrames = totalFrames;

const MainComposition: React.FC = () => {
  const { durationInFrames: total } = useVideoConfig();
  const camera = cameraDrift(useCurrentFrame(), total);

  return (
    <AbsoluteFill
      style={{ transform: camera.transform, transformOrigin: "50% 50%" }}
    >
      <Background />
      <TransitionSeries>
        <TransitionSeries.Sequence durationInFrames={SCENE_COLD_OPEN + TRANSITION}>
          <SceneColdOpen />
        </TransitionSeries.Sequence>
        <TransitionSeries.Transition
          presentation={crossDissolve()}
          timing={linearTiming({ durationInFrames: TRANSITION })}
        />

        <TransitionSeries.Sequence durationInFrames={SCENE_TYPING + TRANSITION}>
          <SceneTyping />
        </TransitionSeries.Sequence>
        <TransitionSeries.Transition
          presentation={crossDissolve()}
          timing={linearTiming({ durationInFrames: TRANSITION })}
        />

        <TransitionSeries.Sequence durationInFrames={SCENE_CLAUDE_WORKS + TRANSITION}>
          <SceneClaudeWorks />
        </TransitionSeries.Sequence>
        <TransitionSeries.Transition
          presentation={crossDissolve()}
          timing={linearTiming({ durationInFrames: TRANSITION })}
        />

        <TransitionSeries.Sequence durationInFrames={SCENE_PAYOFF + TRANSITION}>
          <ScenePayoff />
        </TransitionSeries.Sequence>
        <TransitionSeries.Transition
          presentation={crossDissolve()}
          timing={linearTiming({ durationInFrames: TRANSITION })}
        />

        <TransitionSeries.Sequence durationInFrames={SCENE_END_CARD}>
          <SceneEndCard />
        </TransitionSeries.Sequence>
      </TransitionSeries>
    </AbsoluteFill>
  );
};

export default MainComposition;
